/* ============================================================
   KBL SEARCH STABILITY PATCH
   Canonical search state: prevents the search overlay from
   becoming permanently stuck after deployment/browser restore.
   ============================================================ */
(function(){
  function setSearchState(open){
    const overlay=document.getElementById('searchOverlay');
    const backdrop=document.getElementById('searchBackdrop');
    if(!overlay || !backdrop) return;
    overlay.classList.toggle('open',!!open);
    backdrop.classList.toggle('open',!!open);
    overlay.setAttribute('aria-hidden',open?'false':'true');
    backdrop.setAttribute('aria-hidden',open?'false':'true');
    if(open){
      document.body.classList.add('search-open');
      document.body.style.overflow='hidden';
    }else{
      document.body.classList.remove('search-open');
      document.body.style.overflow='';
    }
  }
  window.openSearch=function(){
    setSearchState(true);
    const input=document.getElementById('globalSearchInput');
    if(input){
      const current=document.getElementById('propertySearch')?.value||'';
      input.value=current;
      try{ renderGlobalSearch(input.value); }catch(_){}
      window.setTimeout(()=>{ try{input.focus();}catch(_){} },80);
    }
  };
  window.closeSearch=function(){
    setSearchState(false);
  };

  // Capture-phase close guarantees the close button/backdrop wins over other
  // document click handlers, even if another handler is added later.
  document.addEventListener('click',function(e){
    if(e.target.closest('#searchClose') || e.target.closest('#searchBackdrop')){
      e.preventDefault();
      e.stopImmediatePropagation();
      window.closeSearch();
    }
  },true);

  document.addEventListener('keydown',function(e){
    if(e.key==='Escape'){
      const overlay=document.getElementById('searchOverlay');
      if(overlay?.classList.contains('open')){
        e.preventDefault();
        e.stopImmediatePropagation();
        window.closeSearch();
      }
    }
  },true);

  // Never allow a stale browser-restored "open" class to trap the page on load.
  window.addEventListener('pageshow',function(){
    const overlay=document.getElementById('searchOverlay');
    const backdrop=document.getElementById('searchBackdrop');
    if(overlay && !overlay.classList.contains('open')){
      overlay.setAttribute('aria-hidden','true');
      backdrop?.setAttribute('aria-hidden','true');
      document.body.classList.remove('search-open');
      document.body.style.overflow='';
    }
  });
})();

// Bind all existing lexical calls/listeners to the canonical stable implementation.
openSearch=window.openSearch;
closeSearch=window.closeSearch;
